import{z as o,x as s,o as t,c as p,q as i,j as A,D as e,d as B,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"自我验证与回溯","description":"","frontmatter":{"title":"自我验证与回溯","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-verification-backtrack.md","filePath":"llm/self-verification-backtrack.md","lastUpdated":1791413859000}'),d={name:"llm/self-verification-backtrack.md"};function D(m,a,C,f,h,c){const r=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="自我验证与回溯" tabindex="-1">自我验证与回溯 <a class="header-anchor" href="#自我验证与回溯" aria-label="Permalink to &quot;自我验证与回溯&quot;">​</a></h1><div class="epigraph"><p>链上写出「不对，重来」，并真的改答案：这是搜索，不是把同一句话再说一遍。</p><footer>—— DeepSeek-R1 报告中的自检与反思；Weng 等 Self-Verification；对照过度思考的空转复核</footer></div><p><a href="/llm/reasoning-length-control">上一课</a>会压掉无用尾部。缺口是：<strong>有用的尾部是验证失败后的回溯，它改变答案。</strong> R1-Zero 在无过程标签下长出这类行为。本课写自我验证与回溯，接到并行思考与 aha。不把 PRM 再讲一遍，只引用 <a href="/llm/process-supervision">过程监督</a> 作为对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结果 RL 不监督中间，却观测到「wait / 重新算」后答案纠正。机制假说：组内对的轨迹更常包含纠正，相对优势强化这些标记。它不是保证：同样标记可以空转（过度思考）。判别：纠正前后抽取的答案是否变、变了之后 \\(R\\) 是否从 0 到 1。</p><p><span class="marginnote">判别的数字实例：一道题链上先写答案 42，出现「wait，重新算」后改成 56。若标准答案是 56 且奖励从 0 变 1，这是有用回溯；若改完还是 42，或改来改去最后没交答案，就是空转复核，按过度思考处理。</span></p><p>Weng 等 Self-Verification 是显式提示或二次前向来验证。R1 是内生写进同一条链。产品可以混合：链内自检 + 链外再跑校验器。二次前向更贵，但验证器不占用思维预算，长度控制更好做。</p><h3 id="回溯需要工作记忆在-token-里" tabindex="-1">回溯需要工作记忆在 token 里 <a class="header-anchor" href="#回溯需要工作记忆在-token-里" aria-label="Permalink to &quot;回溯需要工作记忆在 token 里&quot;">​</a></h3><p>改主意必须覆盖已写出的错误结论。Transformer 靠继续写否定，而不是修改已生成 token。于是链变长。长度控制若禁止否定句，等于禁止回溯。应惩罚重复、不惩罚答案翻转。</p><p><span class="marginnote">直觉类比：Transformer 像用钢笔写字，已写下的字改不了，只能接着写「前面那句作废」。所以「改主意」在物理上就是把链写长——这解释了回溯为什么总让回答变长，也因此不能把长回答一律当坏回答砍掉。</span></p><p><span class="marginnote">监视器若惩罚「我刚才错了」这类句子，会把回溯赶进激活、链上变清白。见 CoT monitorability。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量：答案翻转次数、翻转后准确率、空转复核率。训练：不直接奖励「wait」词频（会刷词）；终局 \\(R\\) 足够。若要促进验证，用过程标签或中途校验器调用（工具课）。解码：预算内保留一段给复核，但用稳定规则早停空转。PRM 可在步骤级拒绝错误前缀，比自然语言「我觉得错了」更硬。</p>',13)),(t(),A(n,null,{default:e(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHAIN%5B%22%E6%80%9D%E7%BB%B4%E9%93%BE%22%5D%20--%3E%20CHK%7B%22%E8%87%AA%E6%A3%80%E5%A4%B1%E8%B4%A5%3F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20ANS%5B%22%E7%BB%99%E5%87%BA%E7%AD%94%E6%A1%88%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20BACK%5B%22%E5%9B%9E%E6%BA%AF%E6%94%B9%E5%86%99%22%5D%0A%20%20BACK%20--%3E%20CHAIN%0A%20%20FLIP%5B%22%E7%AD%94%E6%A1%88%E7%BF%BB%E8%BD%AC%E4%B8%94%20R%E2%86%91%22%5D%20--%3E%20USE%5B%22%E6%9C%89%E7%94%A8%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20LOOP%5B%22%E7%BF%BB%E8%BD%AC%200%20%E6%AC%A1%E7%9A%84%E9%95%BF%E5%A4%8D%E6%A0%B8%22%5D%20--%3E%20OV%5B%22%E8%BF%87%E5%BA%A6%E6%80%9D%E8%80%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"内生自检是强化学习在稀疏 \\(R\\) 下发现的搜索启发式，类似 AlphaZero 的价值回滚，但写在自然语言里。不忠实时，链上写复核、激活里并未重算（后课忠实性）。有用性要以终局 \\(R\\) 为准，不以表面修辞为准。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"aha moment（后课）常与回溯同现，但是突然的策略转折，不是每次自检都有 aha。")],-1)),a[6]||(a[6]=E("p",null,"链内自检与链外验证，各付什么代价：",-1)),(t(),A(n,null,{default:e(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E9%81%93%E9%A2%98%22%5D%20--%3E%20A%5B%22%E9%93%BE%E5%86%85%E8%87%AA%E6%A3%80%EF%BC%9A%E5%90%8C%E4%B8%80%E6%9D%A1%E9%93%BE%E9%87%8C%E5%86%99%20wait%20%E5%B9%B6%E9%87%8D%E7%AE%97%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E9%93%BE%E5%A4%96%E9%AA%8C%E8%AF%81%EF%BC%9A%E7%94%9F%E6%88%90%E5%AE%8C%E5%86%8D%E8%B7%91%E4%BA%8C%E6%AC%A1%E5%89%8D%E5%90%91%E6%88%96%E6%A0%A1%E9%AA%8C%E5%99%A8%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E4%BE%BF%E5%AE%9C%EF%BC%8C%E4%BD%86%E5%8D%A0%E6%80%9D%E7%BB%B4%E9%A2%84%E7%AE%97%EF%BC%8C%E9%93%BE%E6%9B%B4%E9%95%BF%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%BF%A0%E5%AE%9E%EF%BC%9A%E5%98%B4%E4%B8%8A%E5%A4%8D%E6%A0%B8%EF%BC%8C%E6%BF%80%E6%B4%BB%E9%87%8C%E6%B2%A1%E9%87%8D%E7%AE%97%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E6%9B%B4%E8%B4%B5%EF%BC%8C%E4%BD%86%E9%AA%8C%E8%AF%81%E4%B8%8D%E5%8D%A0%E6%80%9D%E7%BB%B4%E9%A2%84%E7%AE%97%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E9%95%BF%E5%BA%A6%E6%8E%A7%E5%88%B6%E6%9B%B4%E5%A5%BD%E5%81%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">常见误区：把「wait」出现的次数直接写进奖励。模型很快学会每题插十句「wait」却一个字不改——词频涨了，答案翻转率没涨。该奖励的是「翻转且变对」这个结果，不是那个词。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无校验器的开放域，「回溯」无法核对是否真改对，可能只是更长的自信。有用回溯以答案翻转且奖励上升为准，不要把 wait 词频写进奖励；长度控制应罚重复、不罚翻转。下一课并行：把串行回溯换成多样本再聚合，用独立样本降低空转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有用回溯改变答案并使 \\(R\\) 上升；空转复核是过度思考。</li><li>不要奖励「wait」词频；靠终局 \\(R\\) 或真过程信号。</li><li>长度控制应罚重复不罚翻转。</li><li>链外校验器 / PRM 比口头自检硬。</li><li>出处：DeepSeek-AI R1；Lightman PRM 作硬验证对照。</li></ul>',5))])}const F=o(d,[["render",D]]);export{k as __pageData,F as default};
